#include "core.h"
#include <iostream>
int main(){std::string line;while(std::getline(std::cin,line)){try{auto request=ep::Parser(line).parse();auto command=request.at("command").text();if(command=="initial"){std::cout<<ep::dump(ryuugin::encode(ryuugin::initial()))<<std::endl;continue;}auto game=ryuugin::decode_state(request.at("state"));if(command=="notation_parse")std::cout<<ep::dump(ryuugin::encode(ryuugin::parse_move(game.position,request.at("text").text())))<<std::endl;else if(command=="notation_format")std::cout<<ep::quote(ryuugin::format_move(game.position,ryuugin::decode_move(request.at("move"))))<<std::endl;else if(command=="roundtrip")std::cout<<ep::dump(ryuugin::encode(game))<<std::endl;else if(command=="identity"){ep::J s;s.type=ep::J::String;s.str=ryuugin::identity(game.position);std::cout<<ep::dump(s)<<std::endl;}else if(command=="legal"){ep::J a;a.type=ep::J::Array;if(!game.result.terminal)for(auto&m:ryuugin::legal(game.position))a.arr.push_back(ryuugin::encode(m));std::cout<<ep::dump(a)<<std::endl;}else if(command=="attacks"){ep::J a;a.type=ep::J::Array;for(int s=0;s<2;++s)for(int i=0;i<81;++i){ep::J b;b.type=ep::J::Bool;b.number=ryuugin::attacked(game.position,{i/9,i%9},ryuugin::Side(s));a.arr.push_back(b);}std::cout<<ep::dump(a)<<std::endl;}else if(command=="apply"||command=="undo"){auto m=ryuugin::decode_move(request.at("move"));auto before=ep::dump(ryuugin::encode(game));auto undo=ryuugin::make(game,m);if(command=="undo"){ryuugin::unmake(game,undo);ep::require(ep::dump(ryuugin::encode(game))==before,"undo loss");}std::cout<<ep::dump(ryuugin::encode(game))<<std::endl;}else if(command=="max_plies"){ryuugin::max_plies(game,int(request.at("limit").integer(1,1000000)));std::cout<<ep::dump(ryuugin::encode(game))<<std::endl;}else throw ep::Error("BAD_COMMAND","diagnostics only; no search");}catch(const std::exception&e){std::cout<<"{\"error\":"<<ep::quote(e.what())<<"}"<<std::endl;}}}
